/**
 * Check if a value is 'empty': null, undefined, empty string, or 0.
 * BUG: uses == which coerces types unexpectedly.
 */
export function isEmpty(value: unknown): boolean {
  return value == null || value == '' || value == 0; // BUG: '0' == 0 is true, 'false' != false etc.
}

/**
 * Check if two values are equal.
 * BUG: uses == instead of ===.
 */
export function isEqual(a: unknown, b: unknown): boolean {
  return a == b; // BUG: 0 == '' is true, false == 0 is true, etc.
}

/**
 * Parse an ID from a string or number.
 * Returns the numeric ID, or null if invalid.
 * BUG: uses == to check for falsy which misses '0' as valid ID.
 */
export function parseId(input: string | number | null | undefined): number | null {
  if (input == null || input == '') { // BUG: input == '' is true for 0 (numeric)
    return null;
  }
  const n = Number(input);
  return isNaN(n) ? null : n;
}

/**
 * Check if array includes value using type-safe comparison.
 * BUG: inner comparison uses == instead of ===.
 */
export function includesStrict<T>(arr: T[], value: T): boolean {
  for (const item of arr) {
    if (item == value) { // BUG: == coerces types
      return true;
    }
  }
  return false;
}

