import { isEmpty, isEqual, parseId, includesStrict } from './utils';

test('isEmpty: null and undefined are empty', () => {
  expect(isEmpty(null)).toBe(true);
  expect(isEmpty(undefined)).toBe(true);
});

test('isEmpty: empty string is empty', () => {
  expect(isEmpty('')).toBe(true);
});

test('isEmpty: string "0" is NOT empty', () => {
  // "0" is a non-empty string — should NOT be considered empty
  expect(isEmpty('0')).toBe(false);
});

test('isEmpty: 0 (number) is empty', () => {
  expect(isEmpty(0)).toBe(true);
});

test('isEqual: strict equality, 0 !== ""', () => {
  expect(isEqual(0, '')).toBe(false);
  expect(isEqual(false, 0)).toBe(false);
  expect(isEqual(null, undefined)).toBe(false);
});

test('isEqual: same values', () => {
  expect(isEqual(1, 1)).toBe(true);
  expect(isEqual('a', 'a')).toBe(true);
});

test('parseId: numeric 0 is a valid ID', () => {
  // 0 is a valid ID — should not return null
  expect(parseId(0)).toBe(0);
  expect(parseId('0')).toBe(0);
});

test('parseId: null and undefined return null', () => {
  expect(parseId(null)).toBe(null);
  expect(parseId(undefined)).toBe(null);
});

test('parseId: empty string returns null', () => {
  expect(parseId('')).toBe(null);
});

test('includesStrict: no coercion', () => {
  expect(includesStrict([1, 2, 3], 1)).toBe(true);
  expect(includesStrict<unknown>([1, 2, 3], '1')).toBe(false); // '1' !== 1
  expect(includesStrict<unknown>([false], 0)).toBe(false); // false !== 0
});
